// Songs.js
import React, { useRef, useState, useEffect } from 'react';
import './Episodes.css';

import albumCover from '../assets/shawty.jpg';
import audioFile  from '../assets/shawtyinlove.mp3';

import pianooo from '../assets/pianooo.PNG';
import cartiwannagotopluto from '../assets/cartiwannagotopluto.png';


const formatTime = (t) => {
  if (!Number.isFinite(t)) return '0:00';
  const m = Math.floor(t / 60);
  const s = Math.floor(t % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
};

const poemLines = [
  "The only thing I can think to rhyme with it is noose",
  "Also, I want the next line to have goose",
  "The way my mother wrote the list of my homes she swapped",
  "I'm writing this poem from the bottom, up",
  "Far away from nowhere, I hid",
  "Well, I guess I did",
];

function Songs() {
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress]   = useState(0);
  const [duration, setDuration]   = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const togglePlay = async () => {
    const a = audioRef.current;
    if (!a) return;

    try {
      if (a.paused) {
        // Ensure we have metadata so duration/progress isn’t NaN
        if (Number.isNaN(a.duration)) await a.play(); else await a.play();
      } else {
        a.pause();
      }
      // Don’t optimistically flip isPlaying; let events set it.
    } catch (err) {
      console.error('Audio play() error:', err);
      // Quick UX hint if the browser blocked it or file missing
      alert('Could not start audio. Check console for details.');
    }
  };

  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;

    const onLoaded = () => setDuration(a.duration || 0);
    const onTime   = () => {
      setCurrentTime(a.currentTime || 0);
      if (a.duration) setProgress((a.currentTime / a.duration) * 100);
    };
    const onPlay   = () => setIsPlaying(true);
    const onPause  = () => setIsPlaying(false);
    const onEnd    = () => { setIsPlaying(false); setProgress(0); setCurrentTime(0); };

    a.addEventListener('loadedmetadata', onLoaded);
    a.addEventListener('timeupdate', onTime);
    a.addEventListener('play', onPlay);
    a.addEventListener('pause', onPause);
    a.addEventListener('ended', onEnd);

    // Optional: preload metadata for quicker starts
    a.preload = 'metadata';
    a.volume = 1; // make sure you’re not muted

    return () => {
      a.removeEventListener('loadedmetadata', onLoaded);
      a.removeEventListener('timeupdate', onTime);
      a.removeEventListener('play', onPlay);
      a.removeEventListener('pause', onPause);
      a.removeEventListener('ended', onEnd);
    };
  }, []);

  return (
    <div className="songs-page">
      <div className="spotify-player">
        <img src={albumCover} alt="Album cover" className="album-art" />
        <div className="track-info">
          <h2>Shawty in Love</h2>
          <p>Playboi Carti</p>
        </div>

        <div className="controls">
          <button onClick={togglePlay} className="play-button" aria-label={isPlaying ? 'Pause' : 'Play'}>
            {isPlaying ? '⏸️' : '▶️'}
          </button>

          <span className="time current">{formatTime(currentTime)}</span>
          <div className="progress-bar" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(progress)}>
            <div className="progress-fill" style={{ width: `${progress}%` }} />
          </div>
          <span className="time duration">{formatTime(duration)}</span>
        </div>

        {/* Add controls temporarily to debug if needed */}
        {/* <audio ref={audioRef} src={audioFile} controls /> */}
        <audio ref={audioRef} src={audioFile} />
      </div>

      {/* decorative images */}
      <img src={pianooo} alt="Piano" className="piano-image" />
      <img src={cartiwannagotopluto} alt="Carti" className="carti-words" />
      <div className='poem'>
        <h2>I wrote something:</h2></div>      

      <div className="first-album">
          {poemLines.map((line, i) => (
            <p key={i}>{line}</p>
          ))}
        </div>

        <div className="second-album">
          {poemLines.map((line, i) => (
            <p key={i}>{line}</p>
          ))}
        </div>
    </div>
  );
}

export default Songs;
