// goal moon images (make sure these filenames match your /assets exactly)
import firstmoon from "./assets/firstmoon.png";
import secondmoon from "./assets/secondmoon.png";
import thirdmoon from "./assets/thirdmoon.png";
import fourthmoon from "./assets/fourthmoon.png";
import fifthmoon from "./assets/fifthmoon.png";
import sixthmoon from "./assets/sixthmoon.png";
import seventhmoon from "./assets/seventhmoon.png";
import eighthmoon from "./assets/eighthmoon.png";

const STORAGE_KEY = "wednesdaynights_goal_moons_v1";

// Keep stable constants OUTSIDE components to avoid hook dependency warnings
const STARRY_PLOUGH = [-122.2660, 37.8530]; // [lng, lat]

// Use demo style for now (no keys). Once it renders reliably, swap to Stadia Toner.
// const STADIA_TONER_STYLE = (key) =>
//   `https://tiles.stadiamaps.com/styles/stamen_toner.json?api_key=${key}`;
const DEMO_STYLE = `https://tiles.stadiamaps.com/styles/stamen_toner.json?api_key=${process.env.REACT_APP_STADIA_KEY}`;

/**
 * Map component that is React-safe:
 * - uses useLayoutEffect so the container has layout before map init
 * - calls resize after load to avoid the "black until resize" issue
 */
function TonerStarryPloughMap() {
  const containerRef = useRef(null);
  const mapRef = useRef(null);

  useLayoutEffect(() => {
    if (!containerRef.current) return;
    if (mapRef.current) return;

    // WebGL sanity check (won't crash)
    const hasWebGL = (() => {
      try {
        const canvas = document.createElement("canvas");
        return !!(canvas.getContext("webgl") || canvas.getContext("experimental-webgl"));
      } catch {
        return false;
      }
    })();
    console.log("WebGL available?", hasWebGL);

    // Start with demo style. If this still doesn't show tiles, it's WebGL/browser.
    const styleUrl = DEMO_STYLE;

    // If you want Stadia Toner later:
    // const stadiaKey = process.env.REACT_APP_STADIA_KEY;
    // const styleUrl = STADIA_TONER_STYLE(stadiaKey);

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: styleUrl,
      center: STARRY_PLOUGH,
      zoom: 15.8,
      pitch: 0,
      bearing: 0,
    });

    mapRef.current = map;

    // Helpful logging
    map.on("error", (e) => console.log("MAP ERROR:", e?.error || e));

    map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");

    // Resize helpers (prevents blank canvas)
    const handleResize = () => map.resize();
    window.addEventListener("resize", handleResize);

    map.on("load", () => {
      requestAnimationFrame(() => map.resize());
    
      map.addSource("starry-plough", {
        type: "geojson",
        data: {
          type: "FeatureCollection",
          features: [
            {
              type: "Feature",
              properties: { name: "The Starry Plough" },
              geometry: { type: "Point", coordinates: STARRY_PLOUGH },
            },
          ],
        },
      });
    
      // ✅ soft purple glow
      map.addLayer({
        id: "plough-glow",
        type: "circle",
        source: "starry-plough",
        paint: {
          "circle-radius": 28,
          "circle-color": "rgba(180, 90, 255, 0.22)", // purple glow
          "circle-blur": 0.95,
        },
      });
    
      // ✅ purple ring
      map.addLayer({
        id: "plough-ring",
        type: "circle",
        source: "starry-plough",
        paint: {
          "circle-radius": 14,
          "circle-color": "rgba(0,0,0,0)",
          "circle-stroke-width": 3,
          "circle-stroke-color": "rgba(180, 90, 255, 0.95)", // purple ring
        },
      });
    
      // ✅ center dot (white so it pops)
      map.addLayer({
        id: "plough-dot",
        type: "circle",
        source: "starry-plough",
        paint: {
          "circle-radius": 4,
          "circle-color": "rgba(255,255,255,1)",
        },
      });
    
      // ✅ LABEL
      map.addLayer({
        id: "plough-label",
        type: "symbol",
        source: "starry-plough",
        layout: {
          "text-field": ["get", "name"],
          "text-font": ["Noto Sans Regular"], // safe default in many styles
          "text-size": 16,
          "text-offset": [0, 1.25],
          "text-anchor": "top",
          "text-allow-overlap": true,
        },
        paint: {
          "text-color": "rgba(180, 90, 255, 1)", // purple label
          "text-halo-color": "rgba(255,255,255,0.92)", // makes it readable
          "text-halo-width": 2,
          "text-halo-blur": 0.5,
        },
      });
    
      map.scrollZoom.disable();
    });
    
    return () => {
      window.removeEventListener("resize", handleResize);
      map.remove();
      mapRef.current = null;
    };
  }, []);

  return (
    <div className="mystic-map-wrap">

      <div ref={containerRef} className="mystic-map" />

      <div className="mystic-map-caption">drag to explore · scroll zoom disabled (on purpose)</div>
    </div>
  );
}

function App() {
  const goals = useMemo(
    () => [
      { id: "crochet_headband", label: "Crochet a pink headband", img: firstmoon },
      { id: "half_marathon", label: "Half marathon", img: secondmoon },
      { id: "no_validation", label: "Absolve myself of the need for external validation", img: thirdmoon },
      { id: "berkeley_map", label: "Make a map of Berkeley", img: fourthmoon },
      { id: "bike_lassen", label: "Bike Lassen", img: fifthmoon },
      { id: "talk_zeke", label: "Talk to Zeke Lunder", img: sixthmoon },
      { id: "twentyfour_inches", label: "24 inches", img: seventhmoon },
      { id: "ten_books", label: "Ten books", img: eighthmoon },
    ],
    []
  );

  const [completed, setCompleted] = useState({});

  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) setCompleted(JSON.parse(raw));
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(completed));
    } catch {
      // ignore
    }
  }, [completed]);

  const toggleGoal = (goalId) => {
    setCompleted((prev) => {
      const next = { ...prev };
      if (next[goalId]) delete next[goalId];
      else next[goalId] = true;
      return next;
    });
  };

  const resetAll = () => setCompleted({});

  const remainingGoals = goals.filter((g) => !completed[g.id]);
  const doneGoals = goals.filter((g) => completed[g.id]);

  const circleRadius = 170;

  return (
    <Router>
      <div>
        {/* Top Section */}
        <div className="top-section">
          <Link to="/" className="site-title">
            Wednesday Nights
          </Link>
          <div className="nav-links-slim">
            <Link to="/Stars">Stars</Link>
            <Link to="/Quizzes">Quizzes</Link>
            <Link to="/Episodes">Episodes</Link>
            <Link to="/horoscope">Horoscope</Link>
            <Link to="/miscellaneous">Miscellaneous</Link>
          </div>
        </div>

        <Routes>
          <Route
            path="/"
            element={
              <div className="main-page">
                <div className="main-content">
                  {/* existing art */}
                  <img src={moonImage} alt="Moon" className="moon-image" />
                  <img src={cloud1} alt="Cloud1" className="cloud1-image" />
                  <img src={cloud2} alt="Cloud2" className="cloud2-image" />
                  <img src={yawningmoon} alt="YawnMoon" className="yawning-moon-image" />
                  <img src={bikingfish} alt="Bikefish" className="bikingfish-image" />
                  <img src={octopus} alt="octopus" className="octopus-image" />

                  <div className="new-year">
                    <h2>New Year, new Sos.</h2>
                  </div>

                  <div className="full-moon">
                    <h2>HAPPY FULL MOON</h2>
                  </div>

                  <div className="moon-commentary">
                    <h2>I’ll give you the reader’s digest version:</h2>
                    <ul>
                      <li>I'm doing horribly.</li>
                      <li>alison stop leaving me on delivered.</li>
                      <li>I want people to stop hiding things from me.</li>
                      <li>I want to feel motivated again.</li>
                      <li>I can’t wait to be a teacher.</li>
                      <li>I can’t wait to go to chester.</li>
                    </ul>
                  </div>

                  <div className="yawn-comm">
                    <h2>
                      this yawning moon is me right now im so tired. at least the moon gets to sleep all
                      day i have to be at work.
                    </h2>
                  </div>

                  {/* ✅ The Map */}
                  <TonerStarryPloughMap />

                  {/* ✅ MOON RING */}
                  <div className="moon-ring">
                    <div className="moon-ring-inner">
                      {remainingGoals.map((goal, idx) => {
                        const n = Math.max(remainingGoals.length, 1);
                        const angle = (360 / n) * idx;

                        return (
                          <button
                            key={goal.id}
                            className="moon-button"
                            onClick={() => toggleGoal(goal.id)}
                            title={`Toggle: ${goal.label}`}
                            aria-label={`Toggle: ${goal.label}`}
                            style={{
                              transform: `translate(-50%, -50%) rotate(${angle}deg) translate(${circleRadius}px) rotate(${-angle}deg)`,
                            }}
                          >
                            <img src={goal.img} alt={goal.label} />
                          </button>
                        );
                      })}

                      <div className="goals-panel">
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
                          <strong>Goals</strong>
                          <button
                            onClick={resetAll}
                            style={{
                              border: "none",
                              background: "transparent",
                              cursor: "pointer",
                              textDecoration: "underline",
                              fontSize: 12,
                            }}
                          >
                            reset
                          </button>
                        </div>

                        <div style={{ marginTop: 10 }}>
                          <div style={{ fontSize: 12, opacity: 0.8, marginBottom: 6 }}>
                            click a moon or checkbox to mark done
                          </div>

                          <div style={{ display: "grid", gap: 6, fontSize: 13 }}>
                            {goals.map((g) => (
                              <label key={g.id} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <input type="checkbox" checked={!!completed[g.id]} onChange={() => toggleGoal(g.id)} />
                                <span style={{ textDecoration: completed[g.id] ? "line-through" : "none" }}>
                                  {g.label}
                                </span>
                              </label>
                            ))}
                          </div>

                          {doneGoals.length === goals.length && (
                            <div style={{ marginTop: 10, fontStyle: "italic" }}>all done ⭐</div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="Checklist">
                    <Checklist />
                  </div>

                
                </div>
              </div>
            }
          />

          {/* other routes unchanged */}
          <Route path="/Stars" element={<Stars />} />
          <Route path="/Quizzes" element={<Quizzes />} />
          <Route path="/Episodes" element={<Episodes />} />
          <Route path="/horoscope" element={<Horoscope />} />
          <Route path="/miscellaneous" element={<Miscellaneous />} />
          <Route path="/mercury" element={<GoodbyeAlex />} />
          <Route path="/Checklist" element={<Checklist />} />
          <Route path="/pollux" element={<McBitch />} />
          <Route path="/lea" element={<TenPM />} />
          <Route path="/northstar" element={<Ifwyou />} />
          <Route path="/sirius" element={<Moons />} />
          <Route path="/witchquiz" element={<WitchQuiz />} />
          <Route path="/rue" element={<Strikeout />} />
          <Route path="/karmaquiz" element={<Karmaquiz />} />
          <Route path="/jonas" element={<Real />} />
          <Route path="/naya" element={<GuessWhatGame />} />
          <Route path="/friendsgiving" element={<FriendsgivingQuiz />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
